import { Fragment, forwardRef, useImperativeHandle, useLayoutEffect, useMemo, useRef, useState, type CSSProperties, type ComponentProps } from "react";
import { Easing, Interactive, Sequence, interpolate, random, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import { createTikTokStyleCaptions, type Caption, type TikTokPage } from "@remotion/captions";

type SpeakerCaption = Caption & { speaker?: string };

interface CaptionBaseProps {
  captions: Caption[];
  combineTokensWithinMilliseconds?: number;
  holdMs?: number;
  fontSize?: number;
  fontWeight?: number;
  color?: string;
  className?: string;
}

const DEFAULT_HOLD_MS = 600;
const MIN_SILENCE_BREAK_MS = 300;

interface CaptionPageWindow {
  page: TikTokPage;
  index: number;
  speaker: string | undefined;
  startMs: number;
  speechEndMs: number;
  endMs: number;
  endsInSilence: boolean;
}

type CaptionTokenStatus = "upcoming" | "active" | "spoken";

interface CaptionTokenState {
  text: string;
  spaceBefore: boolean;
  fromMs: number;
  toMs: number;
  progress: number;
  status: CaptionTokenStatus;
}

interface CaptionPreviousPage {
  page: TikTokPage;
  pageIndex: number;
  tokens: CaptionTokenState[];
}

interface CaptionsState {
  page: TikTokPage;
  pageIndex: number;
  speaker: string | undefined;
  timeMs: number;
  activeIndex: number;
  tokens: CaptionTokenState[];
  sinceStartMs: number;
  untilEndMs: number;
  holdRoomMs: number;
  endsInSilence: boolean;
  previous: CaptionPreviousPage | null;
}

interface CaptionPagingOptions {
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}

const SENTENCE_END = /[.!?…]["')\]]*$/;

function markPageBreaks(captions: SpeakerCaption[]): Caption[] {
  return captions.map((caption, i) => {
    if (caption.pageBreakAfter !== undefined) return caption;
    const next = captions[i + 1];
    const speakerChanges =
      next !== undefined && next.speaker !== caption.speaker;
    return speakerChanges || SENTENCE_END.test(caption.text.trim())
      ? { ...caption, pageBreakAfter: true }
      : caption;
  });
}

function buildCaptionPages(
  captions: SpeakerCaption[],
  {
    combineTokensWithinMilliseconds,
    holdMs = DEFAULT_HOLD_MS,
  }: CaptionPagingOptions,
): CaptionPageWindow[] {
  if (captions.length === 0) return [];
  const { pages } = createTikTokStyleCaptions({
    captions: markPageBreaks(captions),
    combineTokensWithinMilliseconds,
    breakOnSilenceAfterMilliseconds: Math.max(holdMs, MIN_SILENCE_BREAK_MS),
  });
  const speakers = new Map<number, string | undefined>();
  for (const caption of captions) {
    if (!speakers.has(caption.startMs)) {
      speakers.set(caption.startMs, caption.speaker);
    }
  }
  const spoken = pages.filter((page) => page.tokens.length > 0);
  return spoken.map((page, index) => {
    const last = page.tokens[page.tokens.length - 1];
    const speechEndMs = last ? last.toMs : page.startMs;
    const heldUntil = speechEndMs + Math.max(0, holdMs);
    const next = spoken[index + 1];
    const endsInSilence = !next || next.startMs > heldUntil;
    const endMs = endsInSilence
      ? heldUntil
      : Math.max(page.startMs, next.startMs);
    return {
      page,
      index,
      speaker: speakers.get(page.tokens[0].fromMs),
      startMs: page.startMs,
      speechEndMs,
      endMs,
      endsInSilence,
    };
  });
}

function findWindowIndex(windows: CaptionPageWindow[], timeMs: number): number {
  let lo = 0;
  let hi = windows.length - 1;
  let found = -1;
  while (lo <= hi) {
    const mid = (lo + hi) >> 1;
    if (windows[mid].startMs <= timeMs) {
      found = mid;
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  if (found === -1) return -1;
  return timeMs < windows[found].endMs ? found : -1;
}

function tokenProgress(fromMs: number, toMs: number, timeMs: number): number {
  if (timeMs < fromMs) return 0;
  if (toMs <= fromMs) return 1;
  return Math.min(1, (timeMs - fromMs) / (toMs - fromMs));
}

function getTokenStates(
  page: TikTokPage,
  timeMs: number,
): { activeIndex: number; tokens: CaptionTokenState[] } {
  let activeIndex = -1;
  page.tokens.forEach((token, i) => {
    if (token.fromMs <= timeMs) activeIndex = i;
  });
  const tokens = page.tokens.map(
    (token, i): CaptionTokenState => ({
      text: token.text.trim(),
      spaceBefore: i > 0 && /^\s/.test(token.text),
      fromMs: token.fromMs,
      toMs: token.toMs,
      progress: tokenProgress(token.fromMs, token.toMs, timeMs),
      status:
        i < activeIndex ? "spoken" : i === activeIndex ? "active" : "upcoming",
    }),
  );
  return { activeIndex, tokens };
}

function getCaptionsState(
  windows: CaptionPageWindow[],
  timeMs: number,
): CaptionsState | null {
  const found = findWindowIndex(windows, timeMs);
  if (found === -1) return null;
  const window = windows[found];
  const { activeIndex, tokens } = getTokenStates(window.page, timeMs);
  const before = found > 0 ? windows[found - 1] : null;
  const previous =
    before && !before.endsInSilence
      ? {
          page: before.page,
          pageIndex: before.index,
          tokens: getTokenStates(before.page, before.endMs).tokens,
        }
      : null;
  return {
    page: window.page,
    pageIndex: window.index,
    speaker: window.speaker,
    timeMs,
    activeIndex,
    tokens,
    sinceStartMs: timeMs - window.startMs,
    untilEndMs: window.endMs - timeMs,
    holdRoomMs: window.endMs - window.speechEndMs,
    endsInSilence: window.endsInSilence,
    previous,
  };
}

function getExitWindowMs(state: CaptionsState, exitMs: number): number {
  return Math.max(1, Math.min(exitMs, state.holdRoomMs));
}

function groupCaptionWords(
  tokens: CaptionTokenState[],
): { index: number; token: CaptionTokenState }[][] {
  const words: { index: number; token: CaptionTokenState }[][] = [];
  tokens.forEach((token, index) => {
    const current = words[words.length - 1];
    if (!current || token.spaceBefore) {
      words.push([{ index, token }]);
    } else {
      current.push({ index, token });
    }
  });
  return words;
}

function normalizeCaptionWord(text: string): string {
  return text
    .toLowerCase()
    .replace(/[\u2018\u2019]/g, "'")
    .replace(/[^\p{L}\p{N}']/gu, "");
}

function createKeywordMatcher(
  keywords: readonly string[] = [],
): (text: string) => boolean {
  const set = new Set(keywords.map(normalizeCaptionWord).filter(Boolean));
  return (text) => set.has(normalizeCaptionWord(text));
}

function captionWordText(word: { token: CaptionTokenState }[]): string {
  return word.map(({ token }) => token.text).join("");
}

interface CaptionWordRect {
  left: number;
  top: number;
  width: number;
  height: number;
}

function sameRects(a: CaptionWordRect[], b: CaptionWordRect[]): boolean {
  return (
    a.length === b.length &&
    a.every(
      (r, i) =>
        r.left === b[i].left &&
        r.top === b[i].top &&
        r.width === b[i].width &&
        r.height === b[i].height,
    )
  );
}

function useCaptionWordRects(
  pageIndex: number,
  count: number,
): {
  wordRef: (index: number) => (el: HTMLElement | null) => void;
  rects: CaptionWordRect[] | null;
} {
  const elements = useRef<(HTMLElement | null)[]>([]);
  const [measured, setMeasured] = useState<{
    pageIndex: number;
    rects: CaptionWordRect[];
  } | null>(null);

  useLayoutEffect(() => {
    if (pageIndex === -1) return;
    const rects = elements.current.slice(0, count).map((el) =>
      el
        ? {
            left: el.offsetLeft,
            top: el.offsetTop,
            width: el.offsetWidth,
            height: el.offsetHeight,
          }
        : { left: 0, top: 0, width: 0, height: 0 },
    );
    setMeasured((prev) =>
      prev && prev.pageIndex === pageIndex && sameRects(prev.rects, rects)
        ? prev
        : { pageIndex, rects },
    );
  });

  return {
    wordRef: (index) => (el) => {
      elements.current[index] = el;
    },
    rects: measured && measured.pageIndex === pageIndex ? measured.rects : null,
  };
}

function useCaptions({
  captions,
  combineTokensWithinMilliseconds,
  holdMs = DEFAULT_HOLD_MS,
}: {
  captions: SpeakerCaption[];
  combineTokensWithinMilliseconds: number;
  holdMs?: number;
}): CaptionsState | null {
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const windows = useMemo(
    () =>
      buildCaptionPages(captions, { combineTokensWithinMilliseconds, holdMs }),
    [captions, combineTokensWithinMilliseconds, holdMs],
  );
  return getCaptionsState(windows, (frame / fps) * 1000);
}

interface CaptionSplitFlapProps extends CaptionBaseProps {
  tileColor?: string;
}

const ENTER_MS = 160;
const EXIT_MS = 220;
const RISE_EM = 0.14;
const FLIP_MS = 60;
const MIN_SETTLE_MS = 350;
const TILE_W = 0.78;
const TILE_H = 1.2;
const TILE_GAP = 0.06;
const GLYPH_SCALE = 0.8;
const RADIUS = 0.08;
const GLYPHS = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

const enterEasing = Easing.bezier(0.2, 0.8, 0.2, 1);

const clamp = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;

interface FlapFrame {
  current: string;
  next: string;
  progress: number | null;
}

function flapFrame(
  target: string,
  seed: string,
  index: number,
  count: number,
  fromMs: number,
  windowMs: number,
  timeMs: number,
): FlapFrame {
  const flips = 3 + Math.floor(random(`${seed}-flips`) * 4);
  const share = count > 1 ? index / (count - 1) : 1;
  const endMs = fromMs + windowMs * (0.55 + 0.45 * share);
  const flipMs = Math.min(FLIP_MS, (endMs - fromMs) / flips);
  const startMs = endMs - flips * flipMs;
  if (timeMs < startMs) return { current: "", next: "", progress: null };
  if (timeMs >= endMs) return { current: target, next: target, progress: null };
  const glyphAt = (k: number): string => {
    if (k <= 0) return "";
    if (k >= flips) return target;
    return GLYPHS[Math.floor(random(`${seed}-${k}`) * GLYPHS.length)];
  };
  const elapsed = (timeMs - startMs) / flipMs;
  const k = Math.floor(elapsed);
  return { current: glyphAt(k), next: glyphAt(k + 1), progress: elapsed - k };
}

const TOP_HALF = "inset(0 0 50% 0)";
const BOTTOM_HALF = "inset(50% 0 0 0)";

function Leaf({
  char,
  tileColor,
  clipPath,
  transform,
  brightness = 1,
}: {
  char: string;
  tileColor: string;
  clipPath?: string;
  transform?: string;
  brightness?: number;
}) {
  const style: CSSProperties = {
    position: "absolute",
    inset: 0,
    display: "flex",
    alignItems: "center",
    justifyContent: "center",
    background: tileColor,
    borderRadius: `${RADIUS}em`,
    clipPath,
    transform,
    transformOrigin: "50% 50%",
    filter: brightness < 1 ? `brightness(${brightness})` : undefined,
  };
  return (
    <span style={style}>
      <span style={{ fontSize: `${GLYPH_SCALE}em`, lineHeight: 1 }}>
        {char}
      </span>
    </span>
  );
}

function Tile({ frame, tileColor }: { frame: FlapFrame; tileColor: string }) {
  const perspective = `perspective(${TILE_H * 4}em)`;
  const { current, next, progress } = frame;
  return (
    <span
      style={{
        position: "relative",
        display: "inline-block",
        width: `${TILE_W}em`,
        height: `${TILE_H}em`,
        flexShrink: 0,
      }}
    >
      {progress === null ? (
        <Leaf char={current} tileColor={tileColor} />
      ) : (
        <>
          <Leaf char={next} tileColor={tileColor} clipPath={TOP_HALF} />
          <Leaf char={current} tileColor={tileColor} clipPath={BOTTOM_HALF} />
          {progress < 0.5 ? (
            <Leaf
              char={current}
              tileColor={tileColor}
              clipPath={TOP_HALF}
              transform={`${perspective} rotateX(${-180 * progress}deg)`}
              brightness={1 - 0.7 * progress}
            />
          ) : (
            <Leaf
              char={next}
              tileColor={tileColor}
              clipPath={BOTTOM_HALF}
              transform={`${perspective} rotateX(${180 * (1 - progress)}deg)`}
              brightness={0.65 + 0.7 * (progress - 0.5)}
            />
          )}
        </>
      )}
      <span
        aria-hidden
        style={{
          position: "absolute",
          left: 0,
          right: 0,
          top: "50%",
          height: "max(1px, 0.025em)",
          transform: "translateY(-50%)",
          background: "rgba(0, 0, 0, 0.6)",
        }}
      />
    </span>
  );
}

function CaptionSplitFlapBase({
  captions,
  combineTokensWithinMilliseconds = 1000,
  holdMs = DEFAULT_HOLD_MS,
  fontSize = 56,
  fontWeight = 800,
  color = "#ffffff",
  tileColor = "#111111",
  className,
}: CaptionSplitFlapProps) {
  const state = useCaptions({
    captions,
    combineTokensWithinMilliseconds,
    holdMs,
  });
  if (!state) return null;

  const enter = interpolate(
    state.previous ? ENTER_MS : state.sinceStartMs,
    [0, ENTER_MS],
    [0, 1],
    { ...clamp, easing: enterEasing },
  );
  const exit = state.endsInSilence
    ? interpolate(
        state.untilEndMs,
        [0, getExitWindowMs(state, EXIT_MS)],
        [0, 1],
        clamp,
      )
    : 1;

  return (
    <div
      className={className}
      style={{
        fontSize,
        fontWeight,
        color,
        lineHeight: TILE_H + 0.24,
        textAlign: "center",
        opacity: Math.min(enter, exit),
        transform: `translateY(${(1 - enter) * RISE_EM}em)`,
      }}
    >
      {groupCaptionWords(state.tokens).map((word, w) => {
        const first = word[0];
        const fromMs = first.token.fromMs;
        const toMs = word[word.length - 1].token.toMs;
        const windowMs = Math.max(toMs - fromMs, MIN_SETTLE_MS);
        const chars = Array.from(captionWordText(word));
        return (
          <Fragment key={`${state.pageIndex}-${first.index}`}>
            {w > 0 && " "}
            <span
              style={{
                display: "inline-flex",
                gap: `${TILE_GAP}em`,
                verticalAlign: "top",
                paddingInline: `${TILE_GAP}em`,
              }}
            >
              {chars.map((char, c) => (
                <Tile
                  key={c}
                  tileColor={tileColor}
                  frame={flapFrame(
                    char,
                    `${state.pageIndex}-${first.index}-${c}`,
                    c,
                    chars.length,
                    fromMs,
                    windowMs,
                    state.timeMs,
                  )}
                />
              ))}
            </span>
          </Fragment>
        );
      })}
    </div>
  );
}

