type CaptionSplitFlapElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof CaptionSplitFlapBase>;

const CaptionSplitFlapInner = forwardRef<
  HTMLDivElement,
  CaptionSplitFlapElementProps & { readonly controls: SequenceControls | undefined }
